local ActivityMountainDrawTabCell = Class('ActivityMountainDrawTabCell')
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')


function ActivityMountainDrawTabCell:__init()

end

function ActivityMountainDrawTabCell:__delete()

end

function ActivityMountainDrawTabCell:Awake()
	SetButtonAction(self.AnimRoot.gameObject,Bind(self,self.OnTabCellClick))
end

function ActivityMountainDrawTabCell:SetCallBackAndIndex(cb,index)
	self.callBack = cb
	self.index = index
end

function ActivityMountainDrawTabCell:RefreshShow(data)
	self.data = data
	self:RefreshStatusShow()
	self:SetSelectStatus(false)
	
	CfUtils.SetUISwitchImage(self.TextDesc, self.index)
	CfUtils.SetUISwitchImage(self.FinishDesc, self.index)
	CfUtils.SetUISwitchText(self.TextDesc, self.index)
	CfUtils.SetUISwitchText(self.FinishDesc, self.index)
end

function ActivityMountainDrawTabCell:RefreshStatusShow()
	local isFinish = self:IsAllShopItemNoStock()
	local isUnLock =  ActivityCakeUtils.GetActivityCakeMgr():IsUnLockShop(self.data.id)
	self.isUnLock = isUnLock
	KTool.SetActive(self.Underway.gameObject,not isFinish)
	KTool.SetActive(self.StatusLock.gameObject,not isUnLock)
	KTool.SetActive(self.Finish.gameObject,isFinish)
end

function ActivityMountainDrawTabCell:IsAllShopItemNoStock()
	if self.data.isLimit == 1 then
		return false
	end
	local isOver = true
	for i, v in pairs(self.data.list) do
		if v.currentStock ~= 0 then
			isOver = false
			break
		end
	end
	return isOver
end

function ActivityMountainDrawTabCell:OnTabCellClick()
	if not self.isUnLock then
		GameUtils.Toast(localize("抽到特等奖后可进入下一层奖池"))
		return
	end
	
	if self.callBack then
		self.callBack(self.index)
	end
end

function ActivityMountainDrawTabCell:SetSelectStatus(status)
	local aniName = status and "ActivityMountainDrawDialog_Cell_Select" or "ActivityMountainDrawDialog_Cell_Back"
	local state = status and 2 or 1
	CfUtils.SetUISwitchImage(self.ImgCat,state)
	CfUtils.PlayAnimation(self.AnimRoot.gameObject,aniName)
end

function ActivityMountainDrawTabCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActivityMountainDrawTabCell